/* Instant local-first storefront. All transactions are labelled sample operations. */
(() => {
  'use strict';
  const S=window.KairosStore,PAGES=window.KAIROS_PAGES;
  let products=S.products;
  const $=(q,root=document)=>root.querySelector(q),$$=(q,root=document)=>[...root.querySelectorAll(q)];
  const escape=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const money=value=>'PKR '+(Number(value)/100).toLocaleString('en-PK',{maximumFractionDigits:2});
  const cents=value=>Math.round(Number(value)*100);
  const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
  document.documentElement.classList.add('js-enabled');
  const variantMap=new Map();
  function rebuild(){products=S.products;variantMap.clear();products.forEach(p=>p.variants.forEach(v=>variantMap.set(v.id,{...v,product:p})));}
  rebuild();
  const read=(key,fallback)=>{try{return JSON.parse(localStorage.getItem(key))||fallback;}catch{return fallback;}};
  const save=(key,value)=>{try{localStorage.setItem(key,JSON.stringify(value));}catch{toast('Browser storage is full. Remove an uploaded photo in the demo manager.');}};
  let bag=read('kairos-demo-bag-v1',[]).filter(i=>variantMap.has(i.id)&&i.qty>0).map(i=>({id:Number(i.id),qty:Math.min(99,Number(i.qty))}));
  let wishlist=read('kairos-demo-wishlist-v1',[]).filter(id=>products.some(p=>p.id===id));
  let coupon=read('kairos-demo-coupon-v1',false),toastTimer;
  function toast(message){const n=$('.toast');if(!n)return;n.textContent=message;n.hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>n.hidden=true,4200);}
  function totals() {
    const subtotal = bag.reduce((sum, item) => sum + cents(variantMap.get(item.id).price) * item.qty, 0);
    const discount = coupon && subtotal >= 500000 ? Math.round(subtotal / 10) : 0;
    const shipping = bag.length && subtotal - discount < 1500000 ? 25000 : 0;
    return {subtotal, discount, shipping, total: subtotal - discount + shipping};
  }
  function persist() {
    save('kairos-demo-bag-v1', bag); save('kairos-demo-wishlist-v1', wishlist); save('kairos-demo-coupon-v1', coupon);
    $$('[data-cart-count]').forEach(node => {node.textContent = bag.reduce((sum, item) => sum + item.qty, 0);});
    $$('[data-wishlist]').forEach(form => {
      const id = Number(form.action.match(/wishlist\/(\d+)/)?.[1]);
      const button = $('button', form); if (!button) return;
      button.classList.toggle('is-saved', wishlist.includes(id)); button.setAttribute('aria-pressed', String(wishlist.includes(id)));
    });
  }
  function card(product) {
    const saved = wishlist.includes(product.id), image = product.cover;
    return `<article class="product-card"><div class="product-visual"><a href="${product.url}" class="product-image" aria-label="View ${escape(product.name)}"><img src="${image?.thumb || '/static/images/product-placeholder.svg'}" ${image ? `srcset="${image.thumb} 480w, ${image.medium} 960w" sizes="(max-width:760px) 45vw, 25vw"` : ''} width="640" height="800" alt="${escape(image?.alt || product.name)}" loading="lazy"></a><div class="product-badges">${!product.stock ? '<span>Out of stock</span>' : product.sale ? '<span class="sale">The special edit</span>' : product.newArrival ? '<span>New arrival</span>' : ''}</div><form action="/wishlist/${product.id}/toggle/" data-wishlist><button class="icon-button wishlist-button ${saved ? 'is-saved' : ''}" aria-pressed="${saved}" aria-label="Save ${escape(product.name)} to wishlist"><svg><use href="#i-heart"/></svg></button></form><a class="product-discover" href="${product.url}">Discover timepiece <svg><use href="#i-arrow"/></svg></a></div><div class="product-info"><div class="product-category">${escape(product.collectionName)} · Demo</div><a href="${product.url}"><h3>${escape(product.name)}</h3></a><p class="product-price">${money(cents(product.price))} ${Number(product.price) < Number(product.regularPrice) ? `<del>${money(cents(product.regularPrice))}</del>` : ''}</p><span class="variant-count">${product.variants.length} finishes to explore</span></div></article>`;
  }
  function empty(title, text) {return `<div class="empty-state"><svg class="empty-icon"><use href="#i-bag"/></svg><h2>${title}</h2><p>${text}</p><a class="button" href="/shop/">Explore the collection →</a></div>`;}
  function line(item, compact = false) {
    const variant = variantMap.get(item.id), product = variant.product;
    return `<article class="${compact ? 'drawer-item' : 'cart-line'}"><a href="${product.url}"><img src="${variant.image}" alt="${escape(variant.name)}" width="${compact ? 90 : 120}" height="${compact ? 110 : 150}"></a><div>${compact ? '' : `<span class="eyebrow">${escape(product.collectionName)}</span>`}<a href="${product.url}"><${compact ? 'span' : 'h2'}>${escape(product.name)}</${compact ? 'span' : 'h2'}></a><p>${escape(variant.name)} · Qty ${item.qty}</p><strong>${money(cents(variant.price) * item.qty)}</strong><div class="demo-line-actions">${compact ? '' : `<button data-demo-qty="${item.id}" data-step="-1" aria-label="Decrease quantity for ${escape(product.name)}">−</button><span>${item.qty}</span><button data-demo-qty="${item.id}" data-step="1" aria-label="Increase quantity for ${escape(product.name)}">+</button>`}<button class="text-link" data-demo-remove="${item.id}">Remove</button></div></div></article>`;
  }
  function summary(checkout = false) {
    const t = totals();
    return `<div class="summary-line"><span>Subtotal</span><span>${money(t.subtotal)}</span></div>${t.discount ? `<div class="summary-line"><span>KAIROS10 · Sample discount</span><span>−${money(t.discount)}</span></div>` : ''}<div class="summary-line"><span>Sample delivery</span><span>${money(t.shipping)}</span></div><div class="summary-line total"><span>Demo total</span><strong>${money(t.total)}</strong></div>${checkout ? '' : `<form class="coupon-form" data-demo-coupon><label for="demo-coupon">Try the sample coupon: KAIROS10</label><div><input id="demo-coupon" name="code" placeholder="Coupon code" maxlength="40"><button>Apply</button></div><p class="summary-note">10% off a demo subtotal of PKR 5,000 or more.</p>${coupon ? '<button type="button" class="text-link" data-demo-remove-coupon>Remove sample coupon</button>' : ''}</form>`}`;
  }
  const drawer = $('#cart-dialog');
  function renderDrawer() {
    const body = $('[data-cart-body]'); if (!body) return;
    body.innerHTML = bag.length ? `<div class="drawer-items">${bag.map(item => line(item, true)).join('')}</div><div class="drawer-summary"><div><span>Subtotal</span><strong>${money(totals().subtotal)}</strong></div><p>Demo bag · No real purchase or payment.</p><a class="button" href="/checkout/">Try sample checkout →</a><a class="text-link" href="/bag/">View and edit your bag →</a></div>` : empty('Time for something new.', 'Your demo bag is waiting for its first timepiece.');
  }
  function openDrawer() {renderDrawer(); if (drawer && !drawer.open) drawer.showModal();}
  function renderBag() {
    if (location.pathname !== '/bag/') return;
    $('#main').innerHTML = `<section class="wrap section"><div class="section-heading"><div><span class="eyebrow">GOOD CHOICES, TOGETHER</span><h1>Your bag.</h1></div><a class="text-link" href="/shop/">Continue exploring →</a></div>${bag.length ? `<div class="checkout-layout"><section class="cart-lines">${bag.map(item => line(item)).join('')}</section><aside class="order-summary"><span class="eyebrow">YOUR SAMPLE SELECTION</span><h2>Order summary</h2>${summary()}<a class="button" href="/checkout/">Try sample checkout →</a><p class="summary-note">Preview only. Nothing is sent to the store and no payment is collected.</p></aside></div>` : empty('Your next favourite awaits.', 'Discover a watch that feels right at home on your wrist.')}</section>`;
  }
  function renderWishlist() {
    if (location.pathname !== '/wishlist/') return;
    const grid = $('#main .product-grid'); if (!grid) return;
    const selected = products.filter(product => wishlist.includes(product.id));
    grid.innerHTML = selected.length ? selected.map(card).join('') : empty('A little room for inspiration.', 'Tap the heart on a timepiece to save it here in your browser.');
  }
  function renderCheckout() {
    const node = $('#demo-checkout'); if (!node) return;
    if (!bag.length) {node.innerHTML = empty('Start with a timepiece.', 'Add a watch to try the sample checkout.'); return;}
    node.innerHTML = `<p class="demo-checkout-notice"><strong>Demonstration checkout.</strong> No real order, payment or delivery is created. The sample details below are for the layout only.</p><form class="checkout-layout" data-demo-checkout><section class="checkout-fields"><h2>01 / Your details</h2><div class="form-grid"><div class="form-field"><label for="sample-name">Full name</label><input id="sample-name" value="Demo Customer" disabled></div><div class="form-field"><label for="sample-email">Email</label><input id="sample-email" value="preview@example.invalid" disabled></div></div><h2>02 / Your delivery</h2><p class="demo-checkout-notice">Delivery within Lahore only. This preview uses sample contact and address details.</p><div class="form-grid"><div class="form-field full-width"><label for="sample-address">Complete delivery address</label><textarea id="sample-address" rows="3" disabled>House 12, sample street — no delivery will be made</textarea></div><div class="form-field"><label for="sample-city">City</label><input id="sample-city" value="Lahore · delivery only" disabled></div><div class="form-field"><label for="sample-zone">Shipping</label><select id="sample-zone" disabled><option>Lahore · Demo delivery</option></select></div></div><div class="form-grid"><div class="form-field"><label for="sample-mobile">Mobile / WhatsApp number</label><input id="sample-mobile" value="03XX1234567 · sample" disabled></div><div class="form-field"><label for="sample-area">Lahore area</label><input id="sample-area" value="Johar Town · sample" disabled></div><div class="form-field full-width"><label for="sample-map">Delivery location / Google Maps pin</label><input id="sample-map" value="Optional pin in the live checkout" disabled></div></div><h2>03 / Payment, your way</h2><div class="payment-options"><div id="id_payment_method"><label><input type="radio" name="demo_method" value="cod" checked> Cash on delivery · Preview</label><label><input type="radio" name="demo_method" value="bank"> Bank transfer · Preview</label></div></div><p class="demo-checkout-notice">Do not send money. This page has no banking or payment connection.</p><div class="checkbox-field"><input id="demo-acknowledge" type="checkbox" required><label for="demo-acknowledge">I understand this is a sample order, not a purchase.</label></div></section><aside class="order-summary"><span class="eyebrow">YOUR TIMEPIECES</span><h2>Order summary</h2>${bag.map(item => {const v = variantMap.get(item.id);return `<div class="checkout-item"><span>${escape(v.product.name)}<small>${escape(v.name)} × ${item.qty}</small></span><strong>${money(cents(v.price) * item.qty)}</strong></div>`;}).join('')}${summary(true)}<button class="button">Place sample order <svg><use href="#i-arrow"/></svg></button><p class="summary-note">A local demonstration only. No customer information is collected or submitted.</p><a href="/bag/" class="text-link">← Back to your bag</a></aside></form>`;
  }
  function renderOrder() {
    const node = $('#demo-order'), history = $('#demo-history'); if (!node && !history) return;
    const localOrder = read('kairos-demo-order-v1', null);
    const order = S.state.orders.find(o=>o.number===localOrder?.number)||S.state.orders[0]||localOrder;
    if (!order) {const content = empty('Your first chapter is waiting.', 'Try the sample checkout to see the confirmation design.'); if (node) node.innerHTML = content; if (history) history.innerHTML = content; return;}
    if (history) {history.innerHTML = `<a class="history-row" href="/demo-order/"><strong>${escape(order.number)}</strong><span class="status-pill">Sample only</span><span>${money(order.total)}</span><span>View preview ↗</span></a>`; return;}
    node.innerHTML = `<div class="order-success"><span class="success-mark"><svg><use href="#i-check"/></svg></span><span class="eyebrow">A PREVIEW OF YOUR NEXT MOMENT</span><h1>A little moment<br>of <em>anticipation.</em></h1><p>Your sample order preview is ready. No purchase has been made.</p><strong>${escape(order.number)}</strong><div class="order-status"><span>${escape(order.status||'Pending')} · Sample only</span><span>No payment required</span></div></div><div class="checkout-layout"><section><h2>Your sample selection</h2>${order.items.map(item => `<div class="order-item"><div><h3>${escape(item.name)}</h3><p>${escape(item.finish)} · Qty ${item.qty}</p></div><strong>${money(item.amount)}</strong></div>`).join('')}<p class="demo-checkout-notice">Nothing was sent to the store. This preview is saved only in this browser.</p></section><aside class="order-summary"><h2>Preview totals</h2><div class="summary-line"><span>Subtotal</span><span>${money(order.subtotal)}</span></div><div class="summary-line"><span>Sample discount</span><span>−${money(order.discount)}</span></div><div class="summary-line"><span>Sample delivery</span><span>${money(order.shipping)}</span></div><div class="summary-line total"><span>Demo total</span><strong>${money(order.total)}</strong></div><a class="button" href="/shop/">Keep exploring →</a></aside></div>`;
  }
  function renderBrowse() {
    const root = $('.shop-results'); if (!root) return;
    const params = new URLSearchParams(location.search), form = $('.filter-form');
    for (const [key, value] of params) {const field = form?.elements.namedItem(key); if (field && key !== 'page') field.value = value;}
    const collection = params.get('collection') || location.pathname.match(/^\/collections\/([^/]+)/)?.[1] || '';
    const q = (params.get('q') || '').trim().toLowerCase();
    let selection = products.filter(product => (!collection || product.collection === collection) && (!q || [product.name,product.description,product.sku].join(' ').toLowerCase().includes(q)));
    if (location.pathname === '/featured/') selection = selection.filter(p => p.featured);
    if (location.pathname === '/new-arrivals/') selection = selection.filter(p => p.newArrival);
    for (const [key, field] of [['brand','brand'],['strap','strap'],['movement','movement']]) if (params.get(key)) selection = selection.filter(p => p[field] === params.get(key));
    if (params.get('min_price')) selection = selection.filter(p => Number(p.price) >= Number(params.get('min_price')));
    if (params.get('max_price')) selection = selection.filter(p => Number(p.price) <= Number(params.get('max_price')));
    if (params.get('availability')) selection = selection.filter(p => params.get('availability') === 'in_stock' ? p.stock > 0 : p.stock === 0);
    if (params.get('sort') === 'price_asc') selection.sort((a,b) => Number(a.price)-Number(b.price));
    if (params.get('sort') === 'price_desc') selection.sort((a,b) => Number(b.price)-Number(a.price));
    if (!params.get('sort') || params.get('sort') === 'newest') selection.sort((a,b) => new Date(b.createdAt)-new Date(a.createdAt));
    if (params.get('sort') === 'name') selection.sort((a,b) => a.name.localeCompare(b.name));
    if (q) $('.page-heading h1').textContent = `Results for “${params.get('q')}”`;
    const pageCount = Math.max(1,Math.ceil(selection.length / 9)), page = Math.max(1,Math.min(pageCount,Number(params.get('page')) || 1));
    $('.results-meta span', root).textContent = `${selection.length} timepiece${selection.length === 1 ? '' : 's'}`;
    $('.product-grid', root).innerHTML = selection.length ? selection.slice((page-1)*9,page*9).map(card).join('') : empty('No matches. New possibilities.', 'Try another search or loosen a filter to find your next watch.');
    $('.pagination', root)?.remove();
    if (pageCount > 1) {
      const href = number => {const copy = new URLSearchParams(params); copy.set('page',number); return '?' + copy.toString();};
      root.insertAdjacentHTML('beforeend',`<nav class="pagination" aria-label="Pagination">${page > 1 ? `<a href="${escape(href(page-1))}">← Previous</a>` : ''}<span>Page ${page} of ${pageCount}</span>${page < pageCount ? `<a href="${escape(href(page+1))}">Next →</a>` : ''}</nav>`);
    }
  }
  function refreshShopping() {persist(); renderDrawer(); renderBag(); renderCheckout(); renderWishlist();}
  function chooseImage(url, full, alt, selected) {
    const image = $('#main-product-image'); if (!image) return;
    image.removeAttribute('srcset'); image.src = url; image.dataset.full = full || url; image.alt = alt || '';
    if (!reduced) image.animate([{opacity:.4},{opacity:1}],{duration:240});
    $$('[data-thumbnails] button').forEach(button => button.setAttribute('aria-pressed',String(button === selected)));
  }
  function details(p){
    if(!p)return `<section class="section wrap">${empty('This timepiece has moved on.','Explore the rest of the collection for something that feels like you.')}</section>`;
    const v=p.variants.find(v=>String(v.id)===new URLSearchParams(location.search).get('variant'))||p.variants[0],images=v.images?.length?v.images:p.images||[],img=images[0],related=products.filter(x=>x.id!==p.id&&x.collection===p.collection).slice(0,4);
    const spec=(p.specifications||'').split('\n').filter(Boolean).map(line=>{const at=line.indexOf(':');return `<div><dt>${escape(at>-1?line.slice(0,at):'Detail')}</dt><dd>${escape(at>-1?line.slice(at+1).trim():line)}</dd></div>`;}).join('');
    return `<div class="wrap product-page"><div class="breadcrumb"><a href="/">Home</a><span>/</span><a href="/shop/?collection=${p.collection}">${escape(p.collectionName)}</a><span>/</span><span>${escape(p.name)}</span></div><div class="product-detail-grid"><section class="gallery" aria-label="Product images"><button type="button" class="main-photo" data-zoom aria-label="Enlarge product photograph"><img id="main-product-image" src="${img?.medium||'/static/images/product-placeholder.svg'}" data-full="${img?.url||''}" width="960" height="1100" alt="${escape(img?.alt||p.name)}" fetchpriority="high"><span>View the details <svg><use href="#i-plus"/></svg></span></button><div class="gallery-thumbnails" data-thumbnails>${images.map((i,n)=>`<button type="button" data-image="${i.medium}" data-full="${i.url||i.medium}" data-alt="${escape(i.alt)}" aria-label="View image ${n+1}" aria-pressed="${n===0}"><img src="${i.thumb}" width="100" height="100" alt="${escape(i.alt)}"></button>`).join('')}</div></section><div class="product-detail-copy"><span class="eyebrow">${escape(p.collectionName)} / ${escape(p.brandName||'KAIROS COLLECTION')}</span><h1>${escape(p.name)}</h1><div class="detail-price"><span data-variant-price>${money(cents(v.price))}</span><del data-variant-regular ${Number(v.price)>=Number(v.regularPrice||p.regularPrice)?'hidden':''}>${money(cents(v.regularPrice||p.regularPrice))}</del></div><p class="demo-tag">Demo timepiece · Concept photography & illustrative details</p><div class="product-description"><p>${escape(p.description).replace(/\n/g,'<br>')}</p></div><div class="variant-form"><label for="variant-selector">Choose your finish</label><div class="variant-choice"><select id="variant-selector" data-variant-selector data-product-id="${p.id}">${p.variants.map(x=>`<option value="${x.id}" ${v.id===x.id?'selected':''}>${escape(x.name)}</option>`).join('')}</select></div></div><p class="stock-status" data-stock-status>${v.stock?'● '+v.stock+' available · Sample inventory':'Currently out of stock'}</p><p class="sku">SKU: <span data-variant-sku>${escape(v.sku)}</span></p><form class="add-cart-form" data-add-cart><input type="hidden" name="variant_id" value="${v.id}" data-variant-input><div class="purchase-controls"><div class="quantity-control"><button type="button" data-quantity="-1" aria-label="Decrease quantity">−</button><label class="sr-only" for="quantity">Quantity</label><input id="quantity" name="quantity" type="number" min="1" max="${Math.max(1,v.stock)}" value="1" inputmode="numeric"><button type="button" data-quantity="1" aria-label="Increase quantity">+</button></div><button class="button add-bag" data-stock-button ${v.stock?'':'disabled'}><span>Add to bag</span><svg><use href="#i-bag"/></svg></button></div><button class="button button-outline buy-now" name="buy_now" value="1" data-stock-button ${v.stock?'':'disabled'}>Buy now <svg><use href="#i-arrow"/></svg></button><p class="inline-error" data-cart-error role="alert"></p></form><form action="/wishlist/${p.id}/toggle/" data-wishlist><button class="detail-wishlist" aria-pressed="false"><svg><use href="#i-heart"/></svg><span>Save to your wishlist</span></button></form><div class="product-accordions"><details open><summary>The details <svg><use href="#i-plus"/></svg></summary><dl class="specs"><div><dt>Strap</dt><dd>${escape(p.strap||'Not specified')}</dd></div><div><dt>Movement</dt><dd>${escape(p.movement||'Not specified')}</dd></div>${spec}</dl></details><details><summary>Delivery & returns <svg><use href="#i-plus"/></svg></summary><div><p>This is a demonstration collection. Delivery charges shown at sample checkout are illustrative.</p><a href="/pages/shipping/">Delivery information →</a></div></details><details><summary>Warranty & care <svg><use href="#i-plus"/></svg></summary><div><p>Warranty details for these demonstration watches are not specified. Confirm the product’s actual terms before a real purchase.</p></div></details></div></div></div><section class="section"><div class="section-heading"><div><span class="eyebrow">ANOTHER WAY TO EXPRESS YOU</span><h2>Also worth <em>your time.</em></h2></div></div><div class="product-grid four">${related.map(card).join('')}</div></section></div>`;
  }
  function selectVariant(){const select=$('[data-variant-selector]');if(!select)return;const p=products.find(x=>x.id===Number(select.dataset.productId)),v=p?.variants.find(v=>String(v.id)===select.value);if(!v)return;$('[data-variant-input]').value=v.id;$('[data-variant-price]').textContent=money(cents(v.price));$('[data-variant-regular]').textContent=money(cents(v.regularPrice||p.regularPrice));$('[data-variant-regular]').hidden=Number(v.price)>=Number(v.regularPrice||p.regularPrice);$('[data-variant-sku]').textContent=v.sku;$('[data-stock-status]').textContent=v.stock?v.stock+' available · Sample inventory':'Currently out of stock';$('#quantity').max=Math.max(1,v.stock);$('#quantity').value=1;$$('[data-stock-button]').forEach(b=>b.disabled=!v.stock);const imgs=v.images?.length?v.images:p.images||[];const thumb=$('[data-thumbnails]');thumb.innerHTML=imgs.map((i,n)=>`<button type="button" data-image="${i.medium}" data-full="${i.url||i.medium}" data-alt="${escape(i.alt)}" aria-label="View image ${n+1}" aria-pressed="${n===0}"><img src="${i.thumb}" width="100" height="100" alt="${escape(i.alt)}"></button>`).join('');if(imgs.length)chooseImage(imgs[0].medium,imgs[0].url,imgs[0].alt,$('button',thumb));const url=new URL(location.href);url.searchParams.set('variant',v.id);history.replaceState(null,'',url);}
  function optionList(values,emptyText){return `<option value="">${emptyText}</option>`+[...new Set(values.filter(Boolean))].map(x=>`<option value="${escape(x)}">${escape(x)}</option>`).join('');}
  function prepareBrowse(){const f=$('.filter-form');if(!f)return;const c=f.elements.namedItem('collection');if(c)c.innerHTML='<option value="">Every collection</option>'+S.state.categories.map(c=>`<option value="${c.id}">${escape(c.name)}</option>`).join('');for(const key of ['brand','strap','movement']){const el=f.elements.namedItem(key);if(el)el.innerHTML=optionList(products.map(p=>p[key]),key==='brand'?'Every brand':key==='strap'?'All materials':'All movements');}const q=new URLSearchParams(location.search),id=q.get('collection')||location.pathname.match(/^\/collections\/([^/]+)/)?.[1],cat=S.state.categories.find(c=>c.id===id),title=location.pathname==='/featured/'?'The Kairos edit.':location.pathname==='/new-arrivals/'?'Fresh perspectives.':location.pathname==='/search/'?'Find your signature.':cat?.name||'All timepieces.';$('.page-heading h1').textContent=title;if(cat&&c)c.value=cat.id;const old=$('.browse-visual');if(old)old.remove();$('.page-heading')?.insertAdjacentHTML('beforeend',`<div class="browse-visual" aria-hidden="true"><img src="${cat?.image||'/static/images/hero.webp'}" alt="" width="350" height="260"></div><span class="browse-edition">THE KAIROS COLLECTION</span>`);document.title=title+' · KAIROS STORE';}
  function chrome(){const s=S.state.settings;const detail=$('.announcement-detail');if(detail)detail.textContent='LAHORE · PKR';const announcement=$('.announcement>span');if(announcement)announcement.textContent=s.announcement;$$('.brand').forEach(n=>{if(!n.dataset.original)n.dataset.original=n.innerHTML;if(s.logo)n.innerHTML=`<img class="brand-image" src="${s.logo}" alt="KAIROS STORE">`;else if(n.innerHTML!==n.dataset.original)n.innerHTML=n.dataset.original;});const tagline=$('.footer-brand>p:first-of-type');if(tagline)tagline.textContent=s.tagline;let social=$('.footer-socials');if(!social){social=document.createElement('div');social.className='footer-socials';$('.footer-brand')?.append(social);}const wa=s.whatsapp?'https://wa.me/'+s.whatsapp+'?text='+encodeURIComponent('Hello KAIROS STORE, I would like to enquire about your watches.'):'/contact/';const ig=s.instagram||'/contact/';const wi='<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M20 11.5a8 8 0 0 1-12 7L3 20l1.5-4.5A8 8 0 1 1 20 11.5Z"/><path d="M8 7c0 5 3 8 7 8l1-2-3-1-1 1-2-2 1-1-1-3-2 0Z"/></svg>';const ii='<svg viewBox="0 0 24 24" aria-hidden="true"><rect x="3" y="3" width="18" height="18" rx="5"/><circle cx="12" cy="12" r="4"/><circle cx="17" cy="7" r=".7"/></svg>';social.innerHTML=`<a href="${escape(wa)}"${s.whatsapp?' target="_blank" rel="noopener noreferrer"':''}>${wi} WhatsApp</a><a href="${escape(ig)}"${s.instagram?' target="_blank" rel="noopener noreferrer"':''}>${ii} Instagram</a>`;let dock=$('.social-dock');if(!dock){dock=document.createElement('div');dock.className='social-dock';document.body.append(dock);}dock.innerHTML=`<a href="${escape(wa)}" class="social-whatsapp" aria-label="Contact Kairos on WhatsApp" title="${s.whatsapp?'Chat on WhatsApp':'Contact Kairos'}"${s.whatsapp?' target="_blank" rel="noopener noreferrer"':''}>${wi}<span>Let’s talk</span></a><a href="${escape(ig)}" class="social-instagram" aria-label="Kairos Instagram" title="Instagram"${s.instagram?' target="_blank" rel="noopener noreferrer"':''}>${ii}</a>`;$$('#main-nav a').forEach(a=>{a.toggleAttribute('aria-current',a.pathname===location.pathname&&location.pathname!=='/');});const contact=$('.contact-layout');if(contact){let n=$('[data-contact-links]',contact);if(!n){n=document.createElement('div');n.dataset.contactLinks='';contact.prepend(n);}n.innerHTML=s.whatsapp||s.instagram||s.email?`<h2>We’re within reach.</h2><p>${s.email?`<a href="mailto:${escape(s.email)}">${escape(s.email)}</a><br>`:''}${s.whatsapp?`<a href="${escape(wa)}" target="_blank" rel="noopener noreferrer">WhatsApp →</a><br>`:''}${s.instagram?`<a href="${escape(ig)}" target="_blank" rel="noopener noreferrer">Instagram →</a>`:''}</p>`:'<h2>A conversation starts here.</h2><p>Our business contact details will be available when the store launches.</p>';}}
  function home(){const s=S.state.settings;if(!$('.hero'))return;$('.hero .eyebrow').textContent=s.heroEyebrow;$('.hero h1').innerHTML=escape(s.heroLine1)+'<br><em>'+escape(s.heroLine2)+'</em>';$('.hero-description').innerHTML=escape(s.heroDescription).replace(/\n/g,'<br>');$('.hero-bottom>span').textContent=s.tagline.toUpperCase();$('.collection-grid').innerHTML=S.state.categories.map((c,i)=>`<a href="/shop/?collection=${c.id}" class="collection-card reveal"><div class="collection-photo"><img src="${c.image||'/static/images/hero.webp'}" alt="${escape(c.name)} collection" width="720" height="900" loading="lazy"></div><div class="collection-card-copy"><span class="eyebrow">${String(i+1).padStart(2,'0')} / THE COLLECTION</span><h3>${escape(c.name)}</h3><span>Explore collection <svg><use href="#i-arrow"/></svg></span></div></a>`).join('');const grids=$$('.product-grid');if(grids[0])grids[0].innerHTML=products.filter(p=>p.featured).slice(0,4).map(card).join('')||empty('Your next signature awaits.','Explore the complete collection.');if(grids[1])grids[1].innerHTML=products.filter(p=>p.newArrival).slice(0,4).map(card).join('')||products.slice(0,4).map(card).join('');$('.hero').insertAdjacentHTML('beforeend','<div class="hero-orbit" aria-hidden="true"><span>THE ART OF EVERYDAY TIME</span><div class="orbit-clock"><i></i><b></b><em></em></div><small>YOUR STYLE. YOUR TIME.</small></div>');let seen=true;try{seen=sessionStorage.getItem('kairos-demo-intro-v2')==='1';sessionStorage.setItem('kairos-demo-intro-v2','1');}catch{}const welcome=$('#welcome');if(welcome&&!seen&&!reduced){welcome.hidden=false;setTimeout(closeIntro,650);} }
  let revealObserver;
  function animatePage(){revealObserver?.disconnect();if(reduced)return;const main=$('#main');main.animate([{opacity:.75,transform:'translateY(7px)'},{opacity:1,transform:'none'}],{duration:190,easing:'ease-out'});$$('.hero-reveal').forEach((n,i)=>n.animate([{opacity:0,transform:'translateY(20px)'},{opacity:1,transform:'none'}],{duration:500,delay:i*65,easing:'cubic-bezier(.2,.65,.3,1)',fill:'backwards'}));if('IntersectionObserver' in window){revealObserver=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.animate([{opacity:.1,transform:'translateY(20px)'},{opacity:1,transform:'none'}],{duration:520,easing:'ease-out'});revealObserver.unobserve(e.target);}}),{threshold:.06});$$('.reveal').forEach(n=>revealObserver.observe(n));}}
  function renderMain(){rebuild();const path=location.pathname;document.body.classList.toggle('home-page',path==='/');document.body.classList.toggle('admin-mode',window.KairosAdmin.active());if(window.KairosAdmin.active()){window.KairosAdmin.render();return;}let body;if(path.startsWith('/watch/')||path==='/product/'){const id=new URLSearchParams(location.search).get('id'),p=products.find(p=>id?String(p.id)===id:p.url.split('?')[0]===path);body=details(p);document.title=(p?.name||'Explore watches')+' · KAIROS STORE';}else if(path.startsWith('/collections/')||['/shop/','/search/','/featured/','/new-arrivals/'].includes(path)){body=PAGES['/shop/'].html;}else if(path==='/wishlist/'){body='<section class="section wrap"><div class="section-heading"><div><span class="eyebrow">A LITTLE ROOM FOR INSPIRATION</span><h1>Your favourites.</h1></div><a href="/shop/" class="text-link">Explore the collection →</a></div><div class="product-grid four"></div></section>';document.title='Your wishlist · KAIROS STORE';}else {const page=PAGES[path]||PAGES['/'];body=page.html;document.title=page.title;}
    $('#main').innerHTML=body;prepareBrowse();renderBrowse();renderWishlist();renderBag();renderCheckout();renderOrder();home();chrome();persist();if($('.filters details')&&matchMedia('(max-width:760px)').matches)$('.filters details').open=false;if(path==='/contact/')$('.contact-layout .standard-form')?.insertAdjacentHTML('afterbegin','<p class="demo-checkout-notice">Preview form · Messages are not sent.</p>');animatePage();$('#main-nav')?.classList.remove('is-open');$('.mobile-menu-toggle')?.setAttribute('aria-expanded','false');
  }
  const known=url=>!!PAGES[url.pathname]||['/preview-admin/','/admin/','/product/'].includes(url.pathname)||url.pathname.startsWith('/collections/')||url.pathname.startsWith('/watch/');
  function navigate(href,{replace=false,scroll=true}={}){const u=new URL(href,location.href);if(!known(u)){location.href=u.href;return;}$$('dialog[open]').forEach(d=>d.close());if(replace)history.replaceState(null,'',u);else history.pushState(null,'',u);renderMain();if(scroll)window.scrollTo({top:0,behavior:'instant'});const heading=$('#main h1');if(heading){heading.tabIndex=-1;heading.focus({preventScroll:true});}if(u.hash){const target=document.getElementById(u.hash.slice(1));target?.scrollIntoView({behavior:reduced?'instant':'smooth'});}}
  function closeIntro(){const w=$('#welcome');if(!w)return;w.classList.add('closing');setTimeout(()=>w.hidden=true,180);}
  function resetShopping(){bag=[];wishlist=[];coupon=false;rebuild();persist();}
  window.KairosUI={navigate,toast,resetShopping};
  S.subscribe(()=>{rebuild();bag=bag.filter(i=>variantMap.has(i.id));wishlist=wishlist.filter(id=>products.some(p=>p.id===id));persist();chrome();if(!window.KairosAdmin.active())renderMain();});
  window.addEventListener('storage',event=>{if(event.key==='kairos-manager-demo-v2')location.reload();});
  window.addEventListener('popstate',()=>{renderMain();window.scrollTo({top:0,behavior:'instant'});});
  document.addEventListener('click',event=>{
    if(event.defaultPrevented)return;const target=event.target;
    if(target.closest('[data-open-search]')){$('#search-dialog').showModal();$('#global-search').focus();return;}
    if(target.closest('[data-open-cart]')){event.preventDefault();openDrawer();return;}
    if(target.closest('[data-close-dialog]')){target.closest('dialog')?.close();return;}
    const menu=target.closest('.mobile-menu-toggle');if(menu){const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));menu.setAttribute('aria-label',open?'Close navigation':'Open navigation');$('#main-nav').classList.toggle('is-open',open);return;}
    if(target.closest('[data-zoom]')){const source=$('#main-product-image'),image=$('#zoom-image');image.src=source.dataset.full||source.src;image.alt=source.alt;image.style.width='100%';$('[data-zoom-range]').value=100;$('#zoom-dialog').showModal();return;}
    const q=target.closest('[data-quantity]');if(q){const i=$('input[type=number]',q.parentElement);i.value=Math.max(1,Math.min(Number(i.max||99),Number(i.value||1)+Number(q.dataset.quantity)));return;}
    const image=target.closest('[data-image]');if(image){chooseImage(image.dataset.image,image.dataset.full,image.dataset.alt,image);return;}
    const remove=target.closest('[data-demo-remove]');if(remove){bag=bag.filter(i=>i.id!==Number(remove.dataset.demoRemove));refreshShopping();return;}
    const adjust=target.closest('[data-demo-qty]');if(adjust){const item=bag.find(x=>x.id===Number(adjust.dataset.demoQty));if(!item)return;const v=variantMap.get(item.id),count=item.qty+Number(adjust.dataset.step);if(count>v.stock){toast('Only '+v.stock+' in the sample inventory.');return;}if(count<1)bag=bag.filter(x=>x!==item);else item.qty=count;refreshShopping();return;}
    if(target.closest('[data-demo-remove-coupon]')){coupon=false;refreshShopping();return;}
    if(target.closest('[data-skip-intro]')){closeIntro();return;}
    const a=target.closest('a[href]');if(!a||a.target==='_blank'||a.hasAttribute('download')||event.ctrlKey||event.metaKey||event.shiftKey||event.altKey||event.button>0)return;const u=new URL(a.href,location.href);if(u.origin!==location.origin||!known(u))return;if(u.pathname===location.pathname&&u.search===location.search&&u.hash)return;event.preventDefault();navigate(u.href);
  });
  document.addEventListener('change',event=>{if(event.target.matches('[data-variant-selector]'))selectVariant();});
  document.addEventListener('input',event=>{if(event.target.matches('[data-zoom-range]'))$('#zoom-image').style.width=event.target.value+'%';});
  document.addEventListener('keydown',event=>{if(event.key==='Escape'){$('#main-nav')?.classList.remove('is-open');$('.mobile-menu-toggle')?.setAttribute('aria-expanded','false');}});
  $$('dialog:not(#admin-dialog)').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();}}));
  document.addEventListener('submit',event=>{
    if(event.defaultPrevented)return;const form=event.target;
    if(form.matches('.filter-form')||form.matches('#search-dialog form')){event.preventDefault();const params=new URLSearchParams(new FormData(form));for(const [k,v]of [...params])if(!v)params.delete(k);navigate((form.matches('.filter-form')?'/shop/':'/search/')+'?'+params.toString());return;}
    if(form.matches('[data-wishlist]')){event.preventDefault();const id=Number(form.action.match(/wishlist\/(\d+)/)?.[1]);if(!products.some(p=>p.id===id))return;wishlist=wishlist.includes(id)?wishlist.filter(x=>x!==id):[...wishlist,id];persist();renderWishlist();toast(wishlist.includes(id)?'Saved to your wishlist.':'Removed from your wishlist.');return;}
    if(form.matches('[data-add-cart]')){event.preventDefault();const data=new FormData(form),id=Number(data.get('variant_id')),qty=Number(data.get('quantity')),v=variantMap.get(id);if(!v||!Number.isInteger(qty)||qty<1){toast('Choose a valid finish and quantity.');return;}const item=bag.find(x=>x.id===id),next=(item?.qty||0)+qty;if(next>v.stock){$('[data-cart-error]',form).textContent='Only '+v.stock+' available in this sample finish.';return;}if(item)item.qty=next;else bag.push({id,qty});persist();if(event.submitter?.name==='buy_now')navigate('/checkout/');else openDrawer();return;}
    if(form.matches('[data-demo-coupon]')){event.preventDefault();const code=String(new FormData(form).get('code')||'').trim().toUpperCase();if(code!=='KAIROS10'){toast('Try the demonstration coupon KAIROS10.');return;}if(totals().subtotal<500000){toast('The sample coupon needs a subtotal of PKR 5,000.');return;}coupon=true;refreshShopping();toast('Sample coupon applied.');return;}
    if(form.matches('[data-demo-checkout]')){event.preventDefault();if(!bag.length||bag.some(i=>!variantMap.has(i.id)||i.qty>variantMap.get(i.id).stock)){toast('A quantity is no longer available. Please review your bag.');navigate('/bag/');return;}const t=totals(),order={...t,number:'DEMO-'+Math.random().toString(36).slice(2,8).toUpperCase(),createdAt:new Date().toISOString(),status:'Pending',payment:new FormData(form).get('demo_method'),items:bag.map(i=>{const v=variantMap.get(i.id);return{name:v.product.name,finish:v.name,qty:i.qty,amount:cents(v.price)*i.qty};})};try{S.addOrder(order);}catch{toast('Browser storage is full. Remove a demo image before trying again.');return;}save('kairos-demo-order-v1',order);bag=[];coupon=false;persist();navigate('/demo-order/');return;}
    if(form.method.toLowerCase()==='post'){event.preventDefault();toast('This is a design preview. Your message has not been sent.');}
  });
  let scrollPending=false;
  if(!reduced&&!navigator.connection?.saveData&&matchMedia('(min-width:1000px)').matches)window.addEventListener('scroll',()=>{if(scrollPending)return;scrollPending=true;requestAnimationFrame(()=>{const img=$('.hero-image');if(img)img.style.transform=`translate3d(0,${Math.min(24,scrollY*.06)}px,0) scale(1.035)`;scrollPending=false;});},{passive:true});
  chrome();renderMain();persist();
})();
